"1dm":"Le RTBH est gratuit et instantané. Les transits jettent le trafic de la cible en amont, la plupart des exchanges aussi, et environ la moitié de tes peers privés. Tes ports sont sauvés ; la cible reste hors ligne jusqu’à ce que tu le retires.",
