"1dt":"Des frais pour être prêt pour le cloud.",
"1du":"Un PDF mensuel de tes propres graphes de trafic.",
"1dv":"<b>🐘 ALERTE : la CVE-2026-31337 vient de mettre à terre la moitié d’Internet.</b><br>Un bug dans PHP a transformé tous les sites vaguement WordPress de la planète en mineurs de crypto. Le trafic eyeballs baisse de 30 % pendant quelques jours, le temps que le monde patche. Tes clients d’hébergement s’y collent à 3 h du matin.",
"1dw":"Sous NDA",
"1dx":"DE-KICKS Group · Ventes",
"1dy":"<b>DE-KICKS a harmonisé ses tarifs.</b><br>Harmonisé veut dire à la hausse : {ix} coûte maintenant {p} % de plus. Merci pour ta confiance renouvelée.",
"1dz":"<b>Bonne nouvelle ! Tu as été inscrit à {addon}.</b><br>{blurb} {price}/mois, ajouté à ta facture {ix}. Désinscription possible à tout moment dans le panneau IX.",
