"1e0":"Négociations restantes : {n}.",
"1e1":"Comme le blackholing, mais avec un Plus.",
"1e2":"Rend ton port « prêt » pour un produit que tu n’as pas acheté.",
"1e3":"Prix mensuel, rien que pour toi",
"1e4":"Les tarifs sont revus par le Global Commercial Council, qui se réunit à la prochaine pleine lune.",
"1e5":"Plus tu as l’air gros, plus le devis grimpe.",
"1e6":"Signer <small>{price}/mois</small>",
"1e7":"« Merci de ton intérêt ! Nous ne publions pas nos prix, car chaque client est unique. »",
"1e8":"Le même route server, dans un portail couleur or.",
"1e9":"Ils t’ont envoyé un NDA de 14 pages avant même de pouvoir te répéter le prix. Les avocats tablent sur une semaine.",
"1ea":"Ce que paient les autres",
"1eb":"Ton commercial ne répond plus à tes tentatives de négociation.",
"1ec":"Ton commercial est à une conférence à Dubaï. Puis à une autre à Madrid.",
