"1ee":"Ton commercial aimerait d’abord « s’aligner sur la valeur ». Call stratégique calé la semaine prochaine.",
"1ef":"<b>Ta promo {ix} est terminée.</b><br>Le prix revient, plus 10 % de « frais de gestion du programme de fidélité ».",
