"1f0":"L’autre bâtiment",
"1f1":"Un gros FAI s’est trompé de préfixes et a annoncé les tiens pendant 18 minutes. Ses excuses ont pris plus longtemps. Beaucoup de réseaux envoient encore ton trafic dans le vide.",
"1f2":"Une ville futuriste pas encore construite, journée démo à {city}",
"1f3":"<b>Un gigaprojet veut une démo.</b><br>{bw} pendant quatre jours à {city}, pour exhiber une ville qui n’existe encore qu’en images de synthèse. Regarde l’onglet Offres.",
"1f4":"<b>Câble de la Baltique endommagé</b><br>Un cargo a traîné son ancre sur 100 km. Tu n’as aucun lien sur ces câbles.",
"1f5":"<b>Câble endommagé en Baltique</b><br>{n} de tes liens sont coupés pendant environ {d} jours.",
"1f6":"<b>Détournement BGP</b><br>Quelqu’un d’autre annonce tes préfixes. Ta joignabilité reste en baisse tant que ce n’est pas nettoyé.",
"1f7":"<b>Câbles coupés en mer Rouge</b><br>Un navire a traîné son ancre sur plusieurs câbles. Tout le monde accuse tout le monde. Heureusement, tu n’utilises pas ces câbles.",
"1f8":"<b>Câbles coupés en mer Rouge</b><br>{n} de tes liens sous-marins sont coupés pendant environ {d} jours, le temps que les diplomates se disputent au sujet des câbliers.",
"1f9":"Appelle tous ceux que tu connais",
"1fa":"Cogentle et Goggle se sont brouillés sur le peering. Goggle est injoignable via le transit Cogentle.",
"1fb":"<b>Drizzle Electric t’a envoyé un gâteau IPv6.</b><br>Tu l’as revendu pour $8k.",
"1fc":"Escalader à leur CTO",
"1fd":"Faceplant en a eu marre des taxes à l’usage coréennes et a discrètement basculé ses utilisateurs coréens sur ses serveurs de Hong Kong. Les pages se traînent pour tout le monde à Séoul. Le régulateur prépare une amende.",
"1fe":"<b>Faceplant fait passer la Corée par Hong Kong.</b><br>Les utilisateurs de Séoul en reçoivent un cinquième de moins pendant 20 jours, quelle que soit ta connexion.",
"1ff":"<b>Glitch quitte la Corée.</b><br>Le site de streaming de jeux vidéo juge les frais réseau coréens « prohibitifs » et ferme là-bas. Son trafic à Séoul est divisé par deux, pour de bon. Les streamers locaux sont déjà passés à autre chose.",
"1fg":"<b>Golden Week !</b><br>La demande en Chine continentale grimpe de 40 % pendant une semaine.",
"1fh":"<b>Litige sur les permis d’atterrissement à {city}</b><br>Deux ministères revendiquent la même plage. Aucun nouveau lien sous-marin ne peut y atterrir pendant 45 jours.",
"1fi":"<b>{name} frappe {city}</b><br>Plus de courant : ton POP est éteint pour deux jours. Un groupe électrogène l’aurait sauvé.",
"1fj":"<b>{name} frappe {city}</b><br>Le réseau électrique est tombé, mais ton groupe électrogène a maintenu les routeurs en marche.",
"1fk":"{name} a privé {city} d’électricité. Ton POP n’a pas de groupe électrogène.",
"1fl":"<b>La nouvelle saison de « Stranger Pings » vient de sortir !</b><br>La demande des eyeballs grimpe de 25 % pendant une semaine. T’as de la marge ?",
"1fm":"<b>Fusion du control plane optique !</b><br>Toutes les longueurs d’onde louées en {reg} viennent de s’éteindre d’un coup. Ta propre fibre noire va très bien. Voilà pourquoi on possède sa fibre.",
"1fn":"<b>Hors ligne sur ordre à {city}</b><br>Une coupure gouvernementale pour un jour d’examen. Ton POP là-bas est éteint pour la journée.",
"1fo":"<b>Brouille de peering !</b><br>Cogentle a coupé le peering avec Goggle pour 20 jours. Le trafic Goggle via le transit Cogentle a disparu. Fais du peering direct avec Goggle ou passe par un autre upstream.",
"1fp":"Les autorités ont ordonné à tous les réseaux de {city} de couper pendant une journée, le temps des examens nationaux. Oui, ça arrive vraiment.",
"1fq":"<b>Subvention haut débit rural : +$30k</b><br>Le ministère des Tubes aime ce que tu fais.",
"1fr":"<b>Sanctions !</b><br>La République de la Paperasse a sanctionné le fournisseur de vis préféré du fabricant de tes routeurs. Les pièces détachées traînent : pendant 60 jours, les pannes de routeur prennent deux fois plus de temps à réparer.",
"1fs":"<b>Exercice d’internet souverain</b><br>Moscou s’est débranchée du reste d’internet pendant une journée, pour voir ce que ça donne. Tout ce qui sort de Russie est coupé jusqu’à demain.",
"1ft":"<b>La frontière s’est durcie.</b><br>La perte de paquets transfrontalière monte à 35 % pendant 10 jours. Les routes premium sont à peine touchées.",
"1fu":"<b>Les voisins se sont fâchés.</b><br>Une brouille diplomatique ferme les frontières et l’espace aérien autour du Qatar. Tous les liens entre Doha et l’Arabie saoudite ou les Émirats sont coupés pendant environ {n} jours. Fais le grand détour, par la mer.",
"1fv":"<b>Guerre commerciale sur les optiques</b><br>Deux gouvernements ont taxé mutuellement leurs lasers. Les optiques coûtent 40 % plus cher pendant 90 jours.",
"1fw":"<b>Les prix du transit ont baissé de 8 %.</b><br>Ils font ça tous les ans. Personne ne sait où est le plancher.",
"1fx":"Typhon Perte-de-Paquets",
"1fy":"Ton fournisseur de longueurs d’onde a poussé une seule mise à jour malformée sur son control plane optique, et elle a inondé tous les nœuds. Les {n} longueurs d’onde louées que tu as en {reg} sont éteintes. Leur page de statut affiche « dégradé ».",
