"207":"Simple instantané : seul le lien choisi tombe. Les autres liens du même câble, de la même tranchée ou du même fabric restent en place. Les pannes et règles de routage en cours s’appliquent toujours. Ni le temps, ni l’argent, ni la partie ne changent.",
