"24n":"<b>L’Australie est devenue plus australienne.</b><br>Le transit y coûte désormais trois fois le prix habituel, seuls les opérateurs qui en vendent vraiment en Australie en vendent, et Telstraya et Floptus ne font plus que du peering privé, donc leurs sessions à l’IX sont terminées. Vérifie tes POP australiens.",
"24o":"<b>Nouveaux réseaux sur la carte.</b><br>Cette mise à jour a ajouté des réseaux auxquels tu n’es pas encore connecté. Pendant {n} jours, une route de courtoisie gratuite les atteint, pour que ta couverture ne chute pas du jour au lendemain. Peere avec eux, ou achète du transit, avant la fin.",
"24p":"<b>Un truc a buggé dans le NOC.</b><br>Le jeu a continué. Si quelque chose semble bizarre, exporte ta sauvegarde et ouvre une issue sur GitHub.",
