"25a":"Notre groupe Signal : échange des captures d’écran et dispute-toi sur les politiques de peering avec d’autres joueurs. Moins de pelleteuses qu’en vrai.",
"25b":"Dis-le-nous sur GitHub : un court formulaire pour les bugs, les idées, l’équilibrage et les traductions. On les lit tous.",
"25c":"La version réelle, par Thomas Kjær Aabo : une carte interactive et zoomable du vrai trajet de tes paquets, du Wi-Fi à la fibre sous-marine, aujourd’hui, en 2010 et en 1995. Ce jeu invente au fur et à mesure. Celle-là, elle a tout bon.",
"25d":"La version réelle : suis un paquet du Wi-Fi à la fibre sous-marine.",
"25e":"Pose ton propre câble sous-marin…",
"25f":"Ton propre câble sous-marin <small>Tier 1 uniquement</small>",
"25g":"Un réseau mobile qui porte le nom du bruit d’un toast. Tchin-tchin à chaque antenne 5G.",
"25h":"Un opérateur espagnol en vedette sur chaque marché d’Amérique latine, au moins jusqu’à ce qu’il revende le suivant.",
"25i":"Un tout petit opérateur dans un pays où les câbles du monde entier touchent terre. Tarifs à l’avenant.",
"25j":"Le géant du mobile en Afrique, d’un jaune visible depuis l’orbite. Jamais vraiment à vide.",
"25k":"Un edge cloud qui, malgré son nom, est plutôt rapide.",
"25l":"Le grand opérateur australien. G’day, ça fera neuf dollars le mégabit. Pardon, le gigabit.",
"25m":"Le numéro deux de l’Australie. A un jour mis tout le pays hors ligne pendant douze heures avec une mise à jour de routine.",
"25n":"De la fibre dans la Bay Area avec une attitude à l’ancienne : peering ouvert et un vrai humain au téléphone.",
"25o":"Connecte l’outback depuis 550 km d’altitude, puis atterrit dans un data center de Sydney comme tout le monde.",
"25p":"Racheté par Speedyloop, et cherche encore quel nom mettre sur la facture.",
"25q":"Le géant mobile du Brésil. Bien vivant.",
"25r":"Relie l’Europe et l’Asie, et parfois aussi ta table BGP.",
"25s":"Haut débit par le câble dans toute l’Europe centrale. À plus tard, dans la file d’attente du support.",
