"264":"A mis fin au peering gratuit dans toute l’Europe et l’a confié à Inter.Clink, son « partenaire d’interconnexion », qui se fera un plaisir de te vendre une connexion directe. Peering payant uniquement, via un PNI. Dring dring, c’est la facture.",
