"273":"Sans-fil et fibre à Perth, coincé du mauvais côté du Nullarbor. Héberge les machines de cloud gaming, donc son trafic culmine quand la cloche de l’école sonne.",
"274":"Géant philippin. Les demandes de peering sont examinées autour d’une tasse de thé.",
"275":"Géant eyeball rose. Le peering est disponible... contre un abonnement mensuel.",
"276":"Rose, bruyant et presque entièrement IPv6-only. Ricane devant ton CDN IPv4-only.",
"277":"Le petit frère mobile de PLDTea Time. Achetez au grand et vous l'atteignez aussi.",
"278":"Poli, énorme, et désolé pour la facture.",
"279":"L’opérateur historique du Portugal. Ronronne quand tu lui envoies du trafic.",
"27a":"Du mobile prépayé du Paraguay au Guatemala, avec un logo qui rugit.",
"27b":"Haut débit privacy-first à Melbourne depuis 2024. Découvert par le calcul avant que quiconque ne le voie. Fait du peering avec n’importe qui et ne te dira toujours pas qui regarde quoi.",
"27c":"5G privée et fibre pro depuis Oostkamp. Son trafic arrive par rafales industrielles soudaines.",
"27d":"La branche de gros de Proxyminus. Présente sur presque tous les IX de la planète, et à la belge.",
