"27f":"Dit « oi » à chaque foyer du Brésil. La fibre est top, le bilan est encore en convalescence.",
"27g":"Recherche, cartes et un joyeux au revoir.",
"27h":"Recherche, taxis et cartes. Un peu endormi.",
"27i":"Recherche, vidéo et lunettes. Surtout des lunettes.",
"27j":"Protège la moitié du web des hordes de bots. Le Rackstar Partner Program (RPP) installe un cache dans ton rack dès que tu envoies assez de trafic.",
"27k":"Expédie colis et paquets, les deux en 24 h.",
"27l":"Des festivals du shopping qui font fondre les graphes de trafic.",
"27m":"Des vidéos courtes, des graphes de trafic très longs.",
"27n":"Fait chanter tes paquets d’un bout à l’autre de l’Asie-Pacifique.",
"27o":"Petit, rapide et toujours prêt à sauter sur la prochaine offre. Croâ.",
"27p":"Réseau social. Tout le monde finit par s’y vautrer.",
"27q":"Un réseau social à la vision parfaite.",
"27r":"Rapide de nom. Possède une part du câble vers Singapour et n’arrête pas de racheter de petits FAI.",
"27s":"Lancé à Kansas City en 2012 et « bientôt dans ta ville » depuis. Fait du peering avec n’importe qui, presque partout.",
"27t":"A fait des stocks de bande passante en 2020 et il lui reste encore quelques rouleaux.",
"27u":"Diffuse 40 % du trafic du soir. Offre des caches gratuits si tu envoies assez d’eyeballs.",
"27v":"L’opérateur historique de Taïwan. Reste calme pendant que des navires traînent leurs ancres sur ses câbles.",
"27w":"La fille belge de Tangerine : mobile, câble et beaucoup de fibre noire le long des autoroutes wallonnes. Acidulé.",
