"2bi":"Un jeu de navigateur gratuit et cartoon sur le fonctionnement d’Internet. Commence comme un minuscule réseau dans une seule ville, lance le haut débit grand public, achète du transit IP à des opérateurs Tier 1 et Tier 2, fais du peering sur des points d’échange, monte des interconnexions privées et des caches CDN embarqués, et pose de la fibre terrestre, des longueurs d’onde sous-marines et ta propre fibre noire avec du DWDM et des optiques ZR. Signe des clients entreprise, hébergement, trading haute fréquence, GPU pour l’IA et hyperscalers, et garde-les contents pendant que pelleteuses, requins, fat fingers, fuites de routes, attaques DDoS et géopolitique cassent tout.",
