"2ls":"Ouvre à 18 h, amuse-bouches offerts, ferme quand la dernière session tombe.",
"2lt":"Géré par des hackers sous caféine. Le route server a une boule à facettes.",
"2lu":"Peering settlement-free aux racines frisonnes. Les ports 10G et 100G ne coûtent rien. Apporte un ASN et de l’appétit pour les route servers. La mayonnaise est en supplément.",
