"2ly":"Le challenger. Frais chaque matin, un peu rassis le soir.",
"2lz":"Le challenger d’IX Straya. Surgit au bord de chaque ville, y compris celles dont personne d’autre ne s’occupe. Un goût qui s’acquiert, comme la Vegemite.",
