"2mo":"Ports 1.6T, son propre microclimat et deux puces PacketOinker² par line card. Accepte les longueurs d’onde 6.4T en 4×1.6T. Chariot élévateur requis.",
"2mp":"Ports 3.2T, et longueurs d’onde 12.8T livrées en 4×3.2T. Consomme autant qu’une petite ville et arrive avec son propre poste électrique. Il faut un plus gros chariot élévateur.",
"2mq":"Un routeur 3.2T pour le prix d’une voiture d’occasion. L’interface web a neuf cents onglets, et l’un d’eux est celui qu’il te faut.",
"2mr":"Un switch bare-metal sous SONiC open source. Fait économiser une fortune, jusqu’au jour où il plante et qu’il n’y a personne à appeler.",
"2ms":"quelques dizaines de cœurs ARM",
"2mt":"Cent quarante-quatre ports 3.2T et des buffers assez profonds pour y cacher une flotte entière. Démarre toujours avant ton flat white. La barbe a maintenant sa propre barbe.",
"2mu":"un ASIC mystère",
"2mv":"Un network processor reconditionné, au firmware figé dans le temps",
"2mw":"Un monstre aux ports 800G, construit autour de la puce de forwarding Junipurr PacketOinker™. Fait groin-groin à line rate. Accepte les optiques 800ZR+.",
"2mx":"a démarré, a paniqué à cause d’un tiroir de ventilos manquant, et recommence",
"2my":"A racheté le chapeau du magicien. Des tunnels partout, des segments nulle part. Ports 1.6T à prix moyen de gamme.",
"2mz":"Acheté d’occasion sur eBuy. Les ventilos font un bruit de réacteur d’avion.",
"2n":"Passer",
"2n0":"Bâti comme une porte de sauna : lourd, brûlant et quasi incassable. La config est désormais si hiérarchique qu’elle a une famille royale.",
"2n1":"Châssis pas cher, abonnement éternel. Chaque port exige une licence, chaque licence exige un serveur de licences, et le serveur de licences exige une licence.",
"2n2":"Pas cher à l’achat, ruineux à l’usage : une clé de licence pour chaque port, chaque fonction et, paraît-il, les ventilos. Smart Licensing téléphone maison chaque semaine.",
"2n3":"Coûte moins cher qu’un déjeuner et a deux fois plus de ports que le Rusty. Le configurer prend plus de temps que le déjeuner.",
"2n4":"processeur réseau Fin-P6",
"2n5":"processeur réseau Fin-P",
"2n6":"Ingénierie finlandaise : indestructible, d’une minutie extrême, et la CLI ne parle que la config hiérarchique. Démarre comme un lever de soleil nordique.",
"2n7":"Config fixe, buffers profonds, barbe soigneusement taillée et bandeau sur l’œil. Tourne sous EOS, l’Extensible Operating Ship. Démarre avant que ton flat white au lait d’avoine soit prêt, et embarque un shell Python que personne n’a demandé.",
"2n8":"quarante-deux",
"2n9":"a trouvé un firmware plus récent sur la clé USB que quelqu’un a oubliée dedans, et l’installe",
"2na":"compte jusqu’à 2 millions de routes. À voix haute. Une par une",
"2nb":"fait groin-groin pendant l’autotest de chaque PacketOinker sur chaque line card",
"2nc":"lance un fsck sur une carte CompactFlash plus vieille que tes stagiaires",
"2nd":"est en train de « synchroniser les routing engines ». Personne ne sait ce que ça veut dire",
"2ne":"attend que les line cards se mettent d’accord sur qui est le primaire",
