"2nm":"Affûté, rebelle, et parle enfin 400G et 400ZR+.",
"2nn":"Soixante-quatre ports 1.6T sous logiciel open source pour le prix d’une seule carte de ligne. Toujours personne à appeler à 3 h du matin, mais maintenant les plantages sont des plantages à 1.6T.",
"2no":"Le modulaire. Quatre-vingt-seize ports 800G, des buffers assez profonds pour y perdre un navire, et des release notes uniquement sur vinyle. Arrr.",
