"2nq":"merchant silicon Tomahack",
"2nr":"Silicium marchand Tridon't",
"2ns":"Deux cent cinquante-six ports 3.2T et assez de forwarding pour une petite galaxie. Démarre en 42 minutes. Plus personne ne se souvient de la question.",
"2nt":"# Un plafond de 0 Gbps veut dire aucune limite : moins de contrôles, un relais plus rapide.",
"2nu":"Un plafond sur un fournisseur, pour rester à votre engagement sans que la facture au 95e centile ne s’envole. Le trafic au-delà doit trouver une autre sortie, sinon il est perdu.",
"2nv":"AS-path prepending, de 1 à 3 fois. Le reste d’internet voit un chemin plus long et envoie une partie du trafic ailleurs. Une indication, pas un ordre.",
"2nw":"Contrôleur Auto-TE",
"2nx":"Retour à l’éditeur",
"2ny":"# Achetez du transit à un deuxième upstream, puis préférez le moins cher.",
"2nz":"Vérifier (dry run)",
"2o":"Dépensé",
"2o0":"<b>Vérifier (dry run)</b> rejoue le trafic du jour avec le script et montre ce que vous serviriez et ce que coûterait le transit. Rien ne change.",
"2o1":"contrôleur éteint",
"2o2":"# Service client : ceux qui paient un SLA passent en premier.",
"2o3":"<b>Déployer</b> le met en service pour le contrôleur Auto-TE. Si le trafic baisse, corrigez-le ici ou coupez Auto-TE dans l’onglet NOC.",
"2o4":". Tu voulais dire {name} ?",
"2o5":"Pendant une attaque, blackhole la cible en amont (RTBH). Tous les autres sont sauvés ; la cible est coupée jusqu’à ce que tu retires la règle.",
"2o6":"Chaque gigabit qui quitte votre réseau choisit une sortie : une PNI, un port IX ou un port de transit. Livré à lui-même, il prend la moins chère qui a de la place : PNI d’abord, puis l’IX, puis le transit. RouteScript change ces choix, comme le font local-pref, l’AS-path prepending et les drains de maintenance sur de vrais routeurs.",
"2o7":"Remplis à partir de votre réseau tel qu’il est en ce moment. Chargez-en un, lisez-le, vérifiez-le, puis déployez.",
"2o8":"Aide et scripts tout prêts",
"2o9":"Comment marche RouteScript",
"2oa":"# Pas de panique : une règle, difficile de se tromper.",
"2ob":"ligne {n} : {err}",
"2oc":"ligne {n} : je ne comprends pas « {text} ». Essaie : spill at 80%, prefer pni for goggle, avoid transit for netchill, cap transit cogentle at 20 gbps, drain paris, avoid link fra-ams, blackhole ddos",
"2od":"ligne {n} : prepend de 1 à 3 fois",
"2oe":"ligne {n} : spill doit être entre 20 % et 100 %",
"2of":"État : {state} · {rules}",
"2og":"# Fenêtre de maintenance : changez les noms, déployez, faites le travail, puis retirez-le.",
"2oh":"élément manquant : {what}",
"2oi":"Retirer le trafic des sorties d’un POP avant une maintenance. Il transporte encore du trafic s’il n’y a pas d’autre chemin.",
"2oj":"Déplacer le trafic vers la sortie suivante quand un lien ou un port est rempli à ce point, avant qu’il ne perde des paquets. Plus bas est plus sûr, plus haut exploite mieux la capacité.",
"2ok":"règles actives : {n}",
"2ol":"# {net} : {g} via l’IX. Un PNI le sortirait du port partagé.",
"2om":"# {net} : {g} via transit, mais il fait du peering sur {ix}, où tu as un POP. Prends un port là-bas.",
"2on":"# {net} : {g} via transit, mais il fait du peering sur {ix} à {city}, où tu as un POP. Prends un port là-bas.",
"2oo":"Réseaux, fournisseurs et villes s’écrivent par leur nom, en majuscules ou en minuscules. Un début unique suffit aussi (« cog » pour Cogentle), et une faute de frappe reçoit une suggestion.",
"2op":"# Rien à déplacer pour l’instant : prenez d’abord un port IX ou une PNI.",
"2oq":"Une règle par ligne. Un # commence un commentaire, pour laisser des notes à votre vous de 3 h du matin.",
"2or":"# Le peering d’abord : les chemins gratuits avant les payants.",
"2os":"# Grippe-sou : l’upstream le moins cher d’abord, le plus cher en dernier.",
"2ot":"# Régime prepend : une indication au reste d’internet, pas un ordre.",
"2ou":"# Le prepend a besoin de deux upstreams entre lesquels choisir.",
"2ov":"Classer vos upstreams : les préférés d’abord, les évités en dernier. Comme une local-pref sur toute la session.",
"2ow":"Scripts tout prêts",
"2ox":"Rétablir l’exemple",
"2oy":"Envoyer d’abord le trafic d’un réseau par ce type de sortie : pni, ix ou transit. Une local-pref pour un voisin.",
"2oz":"# Boucliers levés : seulement le temps de l’attaque.",
"2p":"Dépensé {x} sur {y}",
"2p0":"Faire bâcler par l’IA",
"2p1":"Faire contourner un lien au trafic, sauf si c’est le seul chemin.",
"2p2":"# Suggéré par l’optimiseur à partir du trafic réel. Il ne s’est jamais fait réveiller à 3 h du matin, alors vérifie, puis déploie.",
"2p3":"{what} « {word} » introuvable",
"2p4":"N’utiliser ce type de sortie pour ce réseau que quand il ne reste rien d’autre.",
"2p5":"Quand les liens saturent, les clients professionnels sont servis d’abord et les particuliers ont ce qui reste.",
"2p6":"Écris des règles, vérifie-les sur le trafic réel, puis déploie. Un mauvais déploiement est un moyen très concret de casser ton réseau.",
