"2q0":"Argent infini, tout débloqué, délais courts. Pas de badges.",
"2q1":"Comme le vrai jeu.",
"2q2":"Presque deux fois plus de pannes, moitié plus longues, deux fois plus de DDoS. Tout activé.",
"2q3":"Pas d’horloge, pas de factures, rien ne casse.",
