"2q7":"D’astreinte",
"2q8":"Un petit réseau, un objectif retors.",
"2q9":"Casse-tête",
"2qa":"Pannes rares, pas de DDoS, pas de singe du chaos, pas de conférences. Les PNI sont actifs dès la commande, les coupures sous-marines se réparent sans navire câblier, les chantiers prennent des jours, les prix ne bougent pas. Clients patients, notifications discrètes et un prêt de sauvetage au lieu de la fin de partie.",
"2qb":"De vrais délais, de vraies pannes, un vrai marché. Le jeu classique.",
