"2qr":"<b>Votre partie n'est pas sauvegardée.</b> Ce navigateur n'autorise pas le jeu à stocker quoi que ce soit (fenêtre privée ou données de sites désactivées). Exportez une sauvegarde pour garder votre réseau.",
"2qs":"<b>Votre partie n'est pas sauvegardée.</b> Votre réseau est devenu trop gros pour le stockage de ce navigateur. Exportez une sauvegarde maintenant et gardez le fichier : c'est votre copie de secours.",
