"2r0":"Choisis un défi",
"2r1":"Partager mon résultat",
"2r2":"Départ à {city} · {mods} · un an, score = pic de trafic. Le même monde pour tout le monde cette semaine.",
"2r3":"Avec de la marge.",
"2r4":"Ton record : {best}.",
