"2r6":"1.6T sur chaque saut de Miami à Madrid et de Lisbonne à Lagos, et 100 Gbps servis",
"2r7":"90 jours d’affilée avec 99,5 % de la demande servie",
"2r8":"99 % de couverture et 150 Gbps servis",
"2r9":"Un chemin du Cap au Caire, avec Lagos et Nairobi aussi sur votre réseau, et 150 Gbps servis",
"2ra":"Un chemin de Los Angeles à Sydney en 1.6T sur chaque saut, un chemin de Los Angeles à Tokyo, et 150 Gbps servis",
"2rb":"Un chemin de Marseille à Singapour, et 80 Gbps entre l’Asie et le reste de ton réseau pendant 30 jours d’affilée",
"2rc":"Amsterdam, capitale européenne de l’hébergement, en pleine saison des botnets. Chaque grille-pain connecté, babyphone et frigo jamais patché de la planète a choisi son camp, et ce n’est pas le tien. Une vague tous les quelques jours, de plus en plus souvent dans les térabits, pendant que tout le reste continue de casser aussi. Tu commences avec du matériel plus gros déjà débloqué, et tu en auras besoin.",
"2rd":"Internet à domicile à Sydney, Melbourne, Brisbane, Adélaïde et Perth, deux câbles différents vers l’étranger, et 500 Gbps servis",
"2re":"Du Cap au Caire",
"2rf":"Le Cap. Construis un réseau à travers l’Afrique : chaque frontière veut son propre permis, et les groupes électrogènes font partie du réseau.",
"2rg":"Cogentle et Goggle ne se parlent plus, et cette fois c’est définitif. Achète le transit pas cher, si tu l’oses.",
"2rh":"Bogotá, Lima, Santiago et São Paulo reliées à Panama, et 150 Gbps servis",
"2ri":"Assurer tout le Carnaval",
"2rj":"Tous les câbles de la mer Rouge sont coupés, tout comme le saut vers l’Égypte. Fais quand même parler Marseille et Singapore : par le tour de l’Afrique, par voie terrestre, ou par l’autre côté de la planète.",
"2rk":"Tous les IX sont gérés par DE-KICKS",
"2rl":"Les eyeballs croissent 50 % plus vite",
"2rm":"La fibre au sous-sol",
"2rn":"Peering Gangnam Style",
"2ro":"Tiens 20 flots, dont 5 au-dessus de 1 Tbps : chaque cible à 97 % ou mieux, personne d’autre touché",
"2rp":"Honolulu, au milieu du Pacifique. Les câbles entre les Amériques, l’Asie et l’Australie sont si longs qu’une longueur d’onde n’y transporte que 400G ou 800G. Arrête la lumière sur une île, fais-la repartir à neuf, et chaque saut devient plus court et plus rapide. Tu commences avec le matériel 1.6T débloqué.",
"2rq":"Accent mi-atlantique",
"2rr":"Que du Spätzle-IX",
"2rs":"Ordre et progrès",
"2rt":"Ponta Delgada, aux Açores, à mi-chemin de l’Atlantique. De la Floride à l’Espagne, c’est juste trop long pour une onde de 1.6T : en ligne droite, elle transporte 1.2T. Atterrissez sur les îles entre les deux, relancez la lumière, et chaque saut passe à 1.6T ou mieux. De Lisbonne à Lagos, le 1.6T passe d’une traite, mais cher : les Canaries coûtent moins. Vous commencez avec l’équipement 1.6T débloqué.",
"2ru":"Des ports sur 15 IX.brrr que votre backbone relie à São Paulo, dont un à Manaus, et 200 Gbps servis",
"2rv":"Couvre 50 % d’internet et sers 300 Gbps",
"2rw":"Crise en mer Rouge",
"2rx":"Rio en partant de zéro. Le Carnaval commence dans 90 jours et veut 400 Gbps pendant cinq jours d’affilée. Le monde entier regarde.",
"2ry":"<b>Mode bac à sable</b><br>Un milliard de dollars et tout débloqué. Chaos : {chaos}. Construis l’internet dont tu as toujours rêvé, et garde une pelleteuse de rechange sous la main.",
"2rz":"<b>Mode bac à sable</b><br>Un milliard de dollars, tout débloqué, et rien ne casse jamais. Construis l’Internet dont tu as toujours rêvé.",
"2s":"Trop lent : trouve un chemin plus rapide.",
"2s0":"São Paulo. Le Brésil est un continent : quarante IX.brrr, des milliers de provedores, et l’Amazonie entre toi et le nord.",
"2s1":"Séoul, où l’expéditeur paie. Chaque Gbps qu’un opérateur livre en Corée te coûte une taxe « l’expéditeur paie » en plus de la facture de transit, les trois opérateurs historiques ne parlent que par un PNI payant, le gigabit à la maison se vend au prix d’un bibimbap et les utilisateurs coréens remarquent chaque milliseconde. Le transit à Tokyo est bon marché, si tes clients supportent le voyage.",
"2s2":"{g} Gbps servis, Séoul bien servie ({q} %), 99 % de portée et un bénéfice mensuel",
"2s3":"Saison des requins : coupures sous-marines deux fois plus probables",
"2s4":"Démarre à Panama City. Rien ne traverse le bouchon du Darién par voie terrestre, et les Andes barrent la route à tout le reste.",
"2s5":"Démarre à Stuttgart, où personne ne vend de transit. Atteins Internet uniquement via peering, PNI, caches et ta propre fibre. Aucun transit, nulle part, jamais.",
"2s6":"Démarre avec seulement $100k",
"2s7":"Sydney, 2013. Le Toilet Paper Group a tiré sa propre fibre jusqu’au sous-sol des immeubles, et le réseau national a crié à l’écrémage. À toi : passe outre le Nearly Broadband Network, paie la taxe et arrive le premier.",
"2s8":"Tallinn, où personne ne vend de transit : votre internet est de l’autre côté de l’eau. Les navires traînent leurs ancres sur les câbles de la Baltique trois fois plus souvent que d’habitude.",
