"ops.mood_annie":"Annie a répondu à trois questions avant que tu les poses, depuis le bureau le plus proche.",
"ops.mood_broke":"{name} a déjà sa liste de courses pour le budget du mois prochain.",
"ops.mood_busy":"{name} a eu une semaine chargée et en est à sa troisième boisson énergisante.",
"ops.mood_kevin":"Kevin dit que c'était plus calme en 2001. Ce n'était pas le cas.",
"ops.mood_new":"{name} a trouvé la machine à café et la CLI, dans cet ordre. Prêt quand tu veux.",
"ops.mood_oops":"{name} fait très attention aujourd'hui. Personne ne parle des descriptions d'interface.",
"ops.mood_outage":"{name} surveille les graphes de la panne et rafraîchit la page de statut. Beaucoup.",
"ops.mood_quiet":"{name} lit tranquillement des RFC. Les graphes sont plats, comme il se doit.",
"ops.mood_sales":"{name} marche un peu plus droit aujourd'hui : quelqu'un a signé pendant sa garde.",
"ops.mood_snag":"{name} est tombé sur un truc bizarre, a mis cet ordre en pause et t'a laissé un post-it.",
"ops.mood_tracy":"Tracy en est au troisième saut d'un traceroute, avec une seule étoile pour l'instant.",
"ops.o_caches":"Accepter les caches gratuits",
"ops.o_caches_d":"Installer chaque cache gratuit qu'un réseau propose, dès que son trafic dans la ville dépasse un seuil.",
