"oq":"Les Tonga tiennent à un seul câble depuis les Fidji. En 2022, un volcan sous-marin l’a coupé et le pays est resté hors ligne pendant des semaines.",
"or":"La capitale de Trinidad, au bout sud de l’arc des îles et à quelques kilomètres du Venezuela.",
"os":"Douze mille habitants et leur premier câble, atterri en août 2025 en route de Tarawa vers Pohnpei.",
"ot":"À vingt minutes de tout, sauf de n’importe où ailleurs.",
"ou":"Villes jumelles, un seul exchange et des passerelles entre les immeubles : Minneapolis peere ici aussi, et en janvier personne ne sort souder une fibre.",
"ov":"Deux millions d’habitants au milieu de la forêt tropicale, avec une zone franche industrielle. La fibre suit les fleuves, et quand elle casse, l’équipe de réparation part en bateau.",
"ow":"Deux exchanges rivaux, l’un à l’université technique, l’autre commercial, et la plupart des réseaux slovaques sont sur les deux.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Une flotte de chalutiers drague pile là où tu dois poser.",
"own_cable.a_whale_has_parked_on_the":"Une baleine s’est garée sur le tracé et refuse de bouger.",
"own_cable.storm_season_the_ship_is_sheltering":"Saison des tempêtes. Le navire s’abrite au port et joue aux cartes.",
"own_cable.the_cable_ship_s_coffee_machine":"La machine à café du câblier est en panne. Personne ne bosse sans café.",
"own_cable.the_crew_fished_out_somebody_else":"L’équipage a repêché le câble de quelqu’un d’autre par erreur et doit le remettre.",
"own_cable.the_seabed_survey_found_an_old":"L’étude des fonds marins a trouvé une vieille mine. Un petit détour, très prudent.",
"ox":"Typhons, séismes et beaucoup de gens très connectés.",
"oy":"Les ingénieurs réseau ukrainiens ont fait tourner Internet malgré les coupures de courant et bien pire. Groupes électrogènes, fibre de secours et redondance partout sont la norme ici, et la scène peering est réputée coriace.",
"oz":"Universités, biotech et un carrier hotel qui a survécu à la plupart de ses opérateurs.",
"p":"{city} s’éteint",
"p0":"L’Uruguay : la fibre dans presque chaque foyer, un ordinateur portable pour chaque écolier, et un opérateur public qui gère presque tout.",
"p1":"Très connectée et mal desservie par la mer : à tout moment, au moins un de ses câbles sous-marins est coupé.",
"p2":"La capitale de la Virginie, où les câbles transatlantiques de Virginia Beach arrivent à l’intérieur des terres vers un exchange neutre : une entrée en Europe plus calme qu’Ashburn.",
"p3":"La chaleur fatale part directement dans les thermes d’à côté.",
"p4":"Quand son unique câble a été coupé en 2018, la Mauritanie a été presque entièrement hors ligne pendant deux jours.",
"p5":"Quand le câble est arrivé en 2025, tout le pays a eu Internet gratuit pendant une journée pour fêter ça.",
"p6":"Là où se rejoignent le Brésil, l’Argentine et le Paraguay, à côté de chutes géantes et d’un barrage hydroélectrique encore plus grand. L’électricité est bon marché, la paperasse douanière non.",
"p7":"Là où les câbles d’Afrique de l’Est touchent terre, avant de remonter par le chemin de fer jusqu’à Nairobi.",
"p8":"Là où les câbles d’Amérique du Sud atterrissent vraiment. L’Europe, l’Afrique et les États-Unis touchent terre ici, puis empruntent un long backhaul vers le sud.",
"p9":"Là où atterrissent les câbles atlantiques vers le sud de l’Afrique. Des manchots sur la plage, du délestage sur le réseau électrique.",
"pa":"Des maisons blanches qui grimpent depuis la Méditerranée. Les câbles partent au nord vers Marseille, et une bonne partie du trafic aussi.",
"pb":"Raccordée de quatre façons pour moins d’un million d’habitants : EASSy, 2Africa et deux câbles courts vers Mayotte.",
"pc":"La Zambie tourne à l’hydroélectricité grâce à un seul grand lac. Les années sèches, le lac baisse, et le réseau électrique aussi.",
"pd":"100G par boîtier",
