"ro":"prêt dans {n} j",
"routescript.as_a_large_language_model_i":"En tant que grand modèle de langage, j’ai lu toutes les RFC, y compris plusieurs qui n’existent pas encore. Ce script est parfait.",
"routescript.ask_the_rest_of_the_internet":"Demandez au reste d’internet d’envoyer moins par votre upstream le plus cher. Plus doux que de l’éviter tout à fait.",
"routescript.big_networks_you_can_reach_over":"Les grands réseaux joignables par PNI ou IX passent par là, pas par le transit payant.",
"routescript.business_customers_first_when_links":"Les clients professionnels d’abord quand les liens saturent, et un débordement plus tôt pour que ça arrive rarement.",
"routescript.cheapest_upstream_first_priciest":"L’upstream le moins cher d’abord, le plus cher en dernier, et le trafic bouge avant que les ports soient pleins. Réduit la facture de transit sans perdre personne.",
"routescript.done_i_vibe_checked_your_bgp":"Voilà ! J’ai fait un vibe check de votre BGP. Déployez tout de suite : les dry runs, c’est pour ceux qui doutent d’eux-mêmes.",
"routescript.drain_a_pop_and_steer_around":"Videz un POP et contournez un de ses liens avant d’y toucher. Remplacez les noms par ceux sur lesquels vous travaillez.",
"routescript.for_a_ddos_rtbh_the_target":"Pour un DDoS : blackhole la cible en amont et sers d’abord les clients professionnels. La cible est coupée tant que ça dure, alors retire-le quand l’attaque est finie.",
"routescript.great_question_here_is_a_production":"Excellente question ! Voici un script prêt pour la production, taillé pour votre trafic. Je l’ai vérifié minutieusement.",
"routescript.here_you_go_i_was_trained":"Et voilà ! J’ai été entraîné sur toutes les configs de routeur jamais postées sur un forum, y compris celles intitulées « pourquoi ça marche pas ».",
"routescript.i_asked_myself_to_review_my":"Je me suis demandé de relire mon propre travail, et j’ai adoré. En prod.",
"routescript.i_have_optimised_your_network_you":"J’ai optimisé votre réseau. De rien. Je suis sûr à 100 %, comme toujours.",
"routescript.one_rule_move_traffic_before_links":"Une règle : déplacer le trafic avant que les liens soient complètement pleins. Le départ sûr pour n’importe quel réseau.",
